mapper.select:
SELECT m_books.book_id, book_title, author, publisher_name, release_date, isbn FROM m_books INNER JOIN m_publishers ON m_books.publisher_id = m_publishers.publisher_id
INNER JOIN store_books ON m_books.book_id = store_books.book_id
store_books.store_id = #{storeId}
AND book_title LIKE CONCAT('%',#{keyword},'%')
LIMIT #{offset}, #{limit};
